mapper.select:
SELECT COALESCE(MAX(seq_no), 0) + 1
FROM job_event
WHERE job_id = #{jobId}

SELECT *
FROM creation_job
WHERE user_id = #{userId}

    AND template_id = #{templateId}


    AND status = #{status}

ORDER BY created_at DESC, id DESC
LIMIT #{limit}

SELECT ja.job_id, a.id, a.owner_user_id, a.original_filename, a.stored_path, a.public_url, a.mime_type, a.size_bytes, a.width, a.height, ja.sort_order FROM job_asset ja JOIN uploaded_asset a ON a.id = ja.asset_id WHERE ja.job_id IN
#{jobId}
ORDER BY ja.job_id, ja.sort_order

mapper.update:
UPDATE creation_job
SET stage    = #{stage},
    progress = #{progress},
    updated_at = #{now}
WHERE id = #{id}
  AND status = 'PROCESSING'

mapper.delete:
DELETE FROM creation_job
WHERE id = #{id}
  AND user_id = #{userId}
  AND status IN ('SUCCEEDED', 'FAILED')
